import heapq
from collections import defaultdict

class FoodRatings:
    def __init__(self, foods: list[str], cuisines: list[str], ratings: list[int]):
        self.food_info = {}
        self.cuisine_heaps = defaultdict(list)
        for f, c, r in zip(foods, cuisines, ratings):
            self.food_info[f] = (c, r)
            heapq.heappush(self.cuisine_heaps[c], (-r, f))

    def changeRating(self, food: str, newRating: int) -> None:
        cuisine, _ = self.food_info[food]
        self.food_info[food] = (cuisine, newRating)
        heapq.heappush(self.cuisine_heaps[cuisine], (-newRating, food))

    def highestRated(self, cuisine: str) -> str:
        h = self.cuisine_heaps[cuisine]
        while h:
            neg_r, food = h[0]
            c, cur_r = self.food_info[food]
            if -neg_r == cur_r:
                return food
            heapq.heappop(h)
        return ""

class FoodRatings {
private:
    struct Comp {
        bool operator()(const std::pair<int, std::string>& a, const std::pair<int, std::string>& b) const {
            if (a.first != b.first) return a.first > b.first;
            return a.second < b.second;
        }
    };
    std::unordered_map<std::string, std::pair<std::string, int>> food_info;
    std::unordered_map<std::string, std::set<std::pair<int, std::string>, Comp>> cuisine_sets;
public:
    FoodRatings(std::vector<std::string>& foods, std::vector<std::string>& cuisines, std::vector<int>& ratings) {
        for (size_t i = 0; i < foods.size(); ++i) {
            food_info[foods[i]] = {cuisines[i], ratings[i]};
            cuisine_sets[cuisines[i]].insert({ratings[i], foods[i]});
        }
    }

    void changeRating(std::string food, int newRating) {
        auto& [cuisine, oldRating] = food_info[food];
        cuisine_sets[cuisine].erase({oldRating, food});
        oldRating = newRating;
        cuisine_sets[cuisine].insert({newRating, food});
    }

    std::string highestRated(std::string cuisine) {
        return cuisine_sets[cuisine].begin()->second;
    }
};

class FoodRatings {
    private static class Entry {
        int rating;
        String food;
        Entry(int rating, String food) {
            this.rating = rating;
            this.food = food;
        }
    }
    private java.util.Map<String, String> foodToCuisine = new java.util.HashMap<>();
    private java.util.Map<String, Integer> foodToRating = new java.util.HashMap<>();
    private java.util.Map<String, java.util.TreeSet<Entry>> cuisineToFoods = new java.util.HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; ++i) {
            foodToCuisine.put(foods[i], cuisines[i]);
            foodToRating.put(foods[i], ratings[i]);
            cuisineToFoods.computeIfAbsent(cuisines[i], k -> new java.util.TreeSet<>((a, b) -> {
                if (a.rating != b.rating) return Integer.compare(b.rating, a.rating);
                return a.food.compareTo(b.food);
            })).add(new Entry(ratings[i], foods[i]));
        }
    }

    public void changeRating(String food, int newRating) {
        String cuisine = foodToCuisine.get(food);
        int oldRating = foodToRating.get(food);
        foodToRating.put(food, newRating);
        java.util.TreeSet<Entry> set = cuisineToFoods.get(cuisine);
        set.remove(new Entry(oldRating, food));
        set.add(new Entry(newRating, food));
    }

    public String highestRated(String cuisine) {
        return cuisineToFoods.get(cuisine).first().food;
    }
}

var FoodRatings = function(foods, cuisines, ratings) {
    this.foodInfo = new Map();
    this.cuisineFoods = new Map();
    for (let i = 0; i < foods.length; ++i) {
        this.foodInfo.set(foods[i], { cuisine: cuisines[i], rating: ratings[i] });
        if (!this.cuisineFoods.has(cuisines[i])) this.cuisineFoods.set(cuisines[i], []);
        this.cuisineFoods.get(cuisines[i]).push(foods[i]);
    }
};

FoodRatings.prototype.changeRating = function(food, newRating) {
    this.foodInfo.get(food).rating = newRating;
};

FoodRatings.prototype.highestRated = function(cuisine) {
    const foods = this.cuisineFoods.get(cuisine);
    let bestFood = foods[0];
    let bestRating = this.foodInfo.get(bestFood).rating;
    for (let i = 1; i < foods.length; ++i) {
        const f = foods[i];
        const r = this.foodInfo.get(f).rating;
        if (r > bestRating || (r === bestRating && f < bestFood)) {
            bestRating = r;
            bestFood = f;
        }
    }
    return bestFood;
};
